(function(){'use strict';
/* Economics Database generator — jahdb-economics-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"public" = Fact-checked public information */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-MACRO-';
var SRC='public';
var RECORD_KIND='economics record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"title":"Supply and Demand","brief":"Supply and demand is economics' core model: prices adjust until the quantity buyers want equals the quantity sellers offer.","points":["The demand curve slopes down: higher prices mean lower quantity demanded.","The supply curve slopes up: higher prices coax out more supply.","Equilibrium price and quantity clear the market — no shortage, no surplus.","Shifts (income, tastes, input costs) move the curves; movements along them respond to price."],"examples":["A coffee crop failure shifting supply left, raising prices.","A housing shortage: demand outpacing supply at current prices."],"history":["Adam Smith described the mechanism (1776); Marshall's Principles (1890) drew the cross.","The model remains the first tool of every economist."],"uses":["Explaining everyday price movements.","Business pricing and production decisions.","Policy: predicting effects of taxes and price controls."],"qa":[["What causes prices to rise?","Demand outgrowing supply, or supply shrinking — shifts, not just greed."],["Do price controls work?","They create shortages (ceilings) or surpluses (floors) — the model predicts it."],["Is the model too simple?","It's a starting lens; real markets add frictions the model abstracts from."]]},{"title":"Elasticity","brief":"Elasticity measures responsiveness — how much quantity changes when price, income, or a related good's price changes.","points":["Price elasticity of demand: % change in quantity over % change in price.","Inelastic goods (insulin, gasoline short-run) barely respond; elastic goods (luxuries) respond strongly.","Revenue is maximized where demand is unit-elastic.","Income and cross-price elasticities classify goods: normal, inferior, substitutes, complements."],"examples":["Cigarette taxes: inelastic demand means revenue rises even as smoking falls slightly.","Airlines pricing seats by estimated elasticity per route."],"history":["Marshall introduced elasticity (1890).","Empirical estimates now guide tax and pricing policy worldwide."],"uses":["Tax policy: who really bears the burden.","Business pricing strategy.","Antitrust: defining markets via substitution."],"qa":[["What does inelastic mean?","Quantity barely budges when price changes — necessities and addictive goods."],["Why do firms care?","Pricing power lives where demand is inelastic."],["Can elasticity change?","Yes — over time, as substitutes appear, demand gets more elastic."]]},{"title":"Opportunity Cost","brief":"Opportunity cost is the value of the next-best alternative given up — the true cost of every choice.","points":["Every decision forgoes alternatives; their value is the opportunity cost.","Sunk costs are gone and irrelevant; only forward-looking costs matter.","Comparative advantage rests on opportunity-cost differences.","Ignoring opportunity cost is the most common economic error."],"examples":["College: tuition plus four years of forgone earnings.","A farmer planting corn forgoes the wheat profit."],"history":["The concept is old; formalized by the Austrians and Wieser (1914).","Buchanan made it central to cost theory."],"uses":["Personal decisions: careers, purchases, time use.","Business: project selection and capital allocation.","Policy: every budget line has an opportunity cost."],"qa":[["Is opportunity cost real money?","It's real value forgone — sometimes cash, sometimes time or options."],["What's the biggest mistake people make?","Counting sunk costs as if they matter going forward."],["How do I apply it daily?","Ask 'what else could this time/money do?' before committing."]]},{"title":"Comparative Advantage","brief":"Comparative advantage says trade benefits everyone when each specializes where their opportunity cost is lowest — even if one side is better at everything.","points":["Absolute advantage (being best) doesn't determine trade; comparative does.","Specialization plus trade leaves both sides with more.","The logic holds for individuals, firms, and nations.","Trade barriers destroy the gains comparative advantage creates."],"examples":["Portugal and England trading wine and cloth in Ricardo's original example.","A lawyer who types fast still hires a secretary — typing's opportunity cost is lawyering."],"history":["Ricardo's Principles (1817) gave the canonical proof.","The most counterintuitive — and most confirmed — idea in economics."],"uses":["Trade policy: the case for openness.","Career strategy: specialize where you're relatively best.","Business: outsource non-core strengths."],"qa":[["Does trade hurt workers?","It displaces some while enriching overall — hence adjustment policy, not protection."],["What if one country is better at everything?","Trade still benefits both — comparative, not absolute, advantage rules."],["Is comparative advantage still true with robots?","Yes — the logic is about opportunity costs, whatever produces."]]},{"title":"Gross Domestic Product (GDP)","brief":"GDP is the total market value of final goods and services produced in a country — the headline score of economic activity.","points":["Measured by expenditure (C+I+G+NX), income, or production — all equal in theory.","Real GDP adjusts for inflation; nominal doesn't.","GDP per capita approximates average material living standards.","GDP misses unpaid work, inequality, environment, and well-being."],"examples":["A recession defined as falling real GDP.","Comparing living standards via GDP per capita across countries."],"history":["Kuznets built national accounts in the 1930s-40s.","Became the global standard after WWII."],"uses":["Macroeconomic policy and forecasting.","Investors gauging economic health.","Debates about what progress really means."],"qa":[["Does GDP measure happiness?","No — it's production, not well-being; complements like HDI exist."],["Why exclude used goods?","To avoid double-counting — only new final production counts."],["Is GDP growing forever sustainable?","It depends on decoupling growth from resource use."]]},{"title":"Inflation","brief":"Inflation is a sustained rise in the general price level — money losing purchasing power over time.","points":["Measured by CPI (consumer basket) or PCE; core excludes volatile food and energy.","Causes: demand-pull (too much spending), cost-push (supply shocks), monetary expansion.","Moderate inflation (~2%) is targeted; high inflation distorts decisions.","Hyperinflation destroys money's functions — historical cautionary tales abound."],"examples":["1970s stagflation: oil shocks plus loose policy.","The 2021-2023 inflation surge from pandemic supply shocks and stimulus."],"history":["Quantity theory (Hume, Friedman); Phillips curve debates (1960s+).","Inflation targeting (1990s+) tamed it in advanced economies."],"uses":["Central banking: the core mandate.","Contracts: indexing wages, pensions, and bonds.","Investing: real vs nominal returns."],"qa":[["Why is 2% inflation the target?","Buffer against deflation with room to cut real rates — a convention that worked."],["Who is hurt by inflation?","Savers and fixed-income earners; borrowers with fixed rates benefit."],["Can inflation be good?","Mild inflation greases wage adjustment; high inflation is corrosive."]]},{"title":"Unemployment","brief":"Unemployment measures labor market slack — but the headline rate hides underemployment, discouragement, and mismatch.","points":["Types: frictional (between jobs), structural (skills mismatch), cyclical (recessions).","The natural rate (NAIRU) is unemployment consistent with stable inflation.","Long-term unemployment scars workers and economies.","Policy trades off inflation vs unemployment in the short run."],"examples":["2008-09: cyclical unemployment spiking to 10% in the US.","Automation displacing routine jobs: structural unemployment."],"history":["Phillips (1958) linked unemployment and wage inflation.","Friedman and Phelps (1968) added expectations — the natural rate."],"uses":["Monetary and fiscal stabilization.","Labor market programs and retraining.","Assessing economic health beyond GDP."],"qa":[["What is full employment?","Not zero unemployment — the natural rate, with only frictional/structural joblessness."],["Why is long-term unemployment worse?","Skills atrophy and employers discriminate — scarring effects."],["Does technology cause permanent unemployment?","So far, no — new jobs emerge, though transitions hurt."]]},{"title":"Interest Rates","brief":"Interest rates are the price of money over time — shaping borrowing, saving, investment, and asset prices.","points":["Real rate = nominal minus expected inflation.","Central banks set short rates; markets set long rates via expectations.","Lower rates stimulate borrowing and investment; higher rates cool demand.","The yield curve (short vs long rates) predicts recessions famously well."],"examples":["Mortgage rates doubling and cooling the housing market.","An inverted yield curve preceding recessions."],"history":["Fisher (1930) formalized real vs nominal rates.","Central-bank rate-setting became the main policy lever."],"uses":["Personal finance: mortgages, savings, debt.","Business investment decisions.","Asset valuation: rates discount all future cash flows."],"qa":[["Why do rates affect stocks?","Higher rates raise discount rates, lowering present values."],["What are negative rates?","Central banks charging for reserves — tried in Europe and Japan."],["Who sets my mortgage rate?","Markets, benchmarked to long-term rates plus lender margins."]]},{"title":"Monetary Policy","brief":"Monetary policy is central banks' management of money and interest rates to stabilize prices and employment.","points":["Tools: policy interest rates, reserve requirements, open-market operations, QE.","Transmission: rates affect borrowing, asset prices, and exchange rates.","Credibility anchors expectations — the most powerful tool.","The zero lower bound forced unconventional tools (QE, forward guidance)."],"examples":["The Fed's 2022-2023 rapid hikes to fight inflation.","QE after 2008 expanding central bank balance sheets."],"history":["Central banking evolved from the 1600s; modern mandates from the 1900s.","Inflation targeting era (1990s+) brought stability."],"uses":["Fighting inflation and recessions.","Financial stability.","Everyone with a loan or savings feels it."],"qa":[["Can central banks just print money?","They create reserves, not spending — and excess causes inflation."],["Why did QE not cause inflation at first?","Banks held reserves; velocity collapsed — context matters."],["What is forward guidance?","Promising future policy to move expectations today."]]},{"title":"Fiscal Policy","brief":"Fiscal policy is government taxing and spending to influence the economy — stimulus in slumps, restraint in booms.","points":["Automatic stabilizers (unemployment insurance, progressive taxes) work without new laws.","Discretionary stimulus: spending hikes or tax cuts in recessions.","Multipliers measure bang-per-buck; they run higher in deep slumps.","Deficits now mean debt later — the intertemporal tradeoff."],"examples":["2009 stimulus packages fighting the Great Recession.","Pandemic-era transfers supporting household incomes."],"history":["Keynes' General Theory (1936) founded activist fiscal policy.","Debates over multipliers never ended."],"uses":["Recession-fighting.","Public investment in infrastructure.","Distributional choices via taxes and transfers."],"qa":[["Does stimulus work?","In deep recessions with idle resources, evidence says yes."],["What's the multiplier?","Roughly 0.5-2 depending on conditions — higher when monetary policy is constrained."],["When should governments tighten?","In booms — surpluses then make room for deficits in busts."]]},{"title":"Central Banking","brief":"Central banks issue currency, set monetary policy, and backstop the financial system as lenders of last resort.","points":["Mandates: price stability, often plus employment and financial stability.","Independence shields policy from short-term political pressure.","Lender of last resort: lending to solvent-but-illiquid banks in panics.","Balance sheets became policy tools via QE."],"examples":["The Fed's 13(3) facilities backstopping markets in 2008 and 2020.","The ECB's 'whatever it takes' (2012) calming the euro crisis."],"history":["The Riksbank (1668) is the oldest; the Fed (1913) the most powerful.","Independence norms spread after 1970s inflation."],"uses":["Price stability for the whole economy.","Crisis-fighting.","Payment systems and currency."],"qa":[["Who owns the Fed?","It's a hybrid: member banks hold stock, but the Board is a federal agency."],["Can politicians control central banks?","Independent ones resist — that's the design; some are less independent."],["What happens if a central bank fails?","It can't go broke in its own currency — credibility is the real constraint."]]},{"title":"Taxation","brief":"Taxation funds government and shapes behavior — its design trades off efficiency, equity, and simplicity.","points":["Types: income, payroll, corporate, sales/VAT, property, wealth.","Progressive taxes take higher shares from higher incomes.","Deadweight loss: taxes distort decisions — good design minimizes it.","Incidence: who really pays often differs from who writes the check."],"examples":["VAT in Europe funding generous welfare states.","Carbon taxes pricing pollution efficiently."],"history":["Income taxes spread in the 1900s; VAT from 1950s France.","Optimal-tax theory (Ramsey, Mirrlees) guides design."],"uses":["Funding everything governments do.","Redistribution and social insurance.","Correcting externalities (Pigouvian taxes)."],"qa":[["What is the best tax?","Economists favor broad-based, low-rate taxes on consumption or land."],["Do corporations really pay corporate tax?","Incidence falls on workers, shareholders, or consumers — debated."],["Why not just tax the rich more?","Trade-offs: revenue, avoidance, and growth effects all matter."]]},{"title":"Government Debt","brief":"Government debt is accumulated deficits — sustainable when economies grow faster than interest accrues, dangerous otherwise.","points":["Debt dynamics: primary balances, interest rates, and growth determine the path.","Debt in own currency differs from foreign-currency debt (no default forced).","High debt can crowd out private investment or constrain crisis response.","Austerity vs stimulus: the eternal fiscal debate."],"examples":["Japan's 250%+ debt-to-GDP sustained by domestic savers.","Eurozone debt crisis (2010s): foreign-currency-like constraints biting."],"history":["Hamilton vs Jefferson debated US debt from the founding.","Modern debates: Reinhart-Rogoff, MMT, and secular stagnation."],"uses":["Fiscal space for crises.","Intergenerational fairness.","Investor assessment of sovereign risk."],"qa":[["Is government debt like household debt?","No — governments live forever, borrow in own currency, and affect the economy."],["How much debt is too much?","No magic number; it depends on growth, rates, and currency sovereignty."],["Should we worry about the debt?","About trajectory and purpose, not the level alone."]]},{"title":"International Trade","brief":"International trade lets countries consume beyond their own production — the engine of global prosperity and political friction.","points":["Gains from specialization and comparative advantage.","Trade deficits reflect saving-investment balances, not 'losing'.","Supply chains fragment production across borders.","Protectionism (tariffs, quotas) helps some producers, hurts consumers."],"examples":["An iPhone assembled from parts made in dozens of countries.","US-China trade tensions reshaping supply chains."],"history":["GATT (1948) to WTO (1995) liberalized trade globally.","Hyperglobalization (1990s-2008) then partial retrenchment."],"uses":["Cheaper, more varied goods for consumers.","Growth for exporting nations.","Geopolitics: trade as leverage and vulnerability."],"qa":[["Are trade deficits bad?","Not inherently — they mirror capital inflows and saving patterns."],["Do tariffs protect jobs?","Some, at high cost to consumers and other industries."],["What is reshoring?","Bringing production home for resilience — trading efficiency for security."]]},{"title":"Exchange Rates","brief":"Exchange rates price one currency in another — moving with interest rates, trade, and expectations.","points":["Floating rates adjust automatically; fixed rates need intervention.","Purchasing power parity anchors long-run rates; speculation drives short-run.","Strong currency: cheap imports, expensive exports — and vice versa.","Currency crises erupt when pegs collapse under pressure."],"examples":["The dollar's 2022 surge on Fed tightening.","The pound's 1992 ERM exit (Black Wednesday)."],"history":["Bretton Woods (1944-71) fixed rates; floating since.","Euro (1999) merged European currencies."],"uses":["Travel, trade, and investment decisions.","Emerging-market stability.","Corporate hedging."],"qa":[["What makes currencies move?","Interest differentials, growth, risk appetite, and expectations."],["Strong dollar: good or bad?","Good for US consumers and travelers; bad for exporters."],["Should countries fix their exchange rate?","It buys stability but forfeits monetary independence."]]},{"title":"Market Competition","brief":"Competition disciplines firms — pushing prices down, quality up, and innovation forward.","points":["Perfect competition: many sellers, identical goods, zero long-run profits.","Real markets sit between perfect competition and monopoly.","Contestability: even the threat of entry disciplines incumbents.","Antitrust policy preserves competition against concentration."],"examples":["Airlines on competitive routes: low fares, thin margins.","Tech platforms' network effects tipping toward dominance."],"history":["Smith praised competition (1776); antitrust law began with Sherman (1890).","Chicago School reshaped antitrust toward consumer welfare."],"uses":["Consumer protection via rivalry.","Innovation incentives.","Regulatory design."],"qa":[["Is competition always good?","Mostly, but it can underprovide public goods and race to the bottom on standards."],["Why are some industries concentrated?","Scale economies, network effects, and regulation create natural oligopolies."],["What is perfect competition good for?","A benchmark — real policy aims for workable competition."]]},{"title":"Monopoly","brief":"A monopoly — one seller — restricts output and raises prices, capturing value that competition would give consumers.","points":["Sources: control of inputs, network effects, patents, regulation.","Deadweight loss: mutually beneficial trades that never happen.","Natural monopoly: one firm cheapest (utilities) — regulated, not broken up.","Rent-seeking: spending to get monopoly rather than to compete."],"examples":["Standard Oil's breakup (1911).","AT&T's breakup (1984) unleashing telecom competition."],"history":["Sherman Act (1890); Clayton and FTC Acts (1914).","Modern tech monopolization cases ongoing."],"uses":["Antitrust enforcement.","Utility regulation.","Patent policy balancing innovation and monopoly."],"qa":[["Are all monopolies bad?","Natural monopolies can be efficient if regulated; others harm consumers."],["What is a natural monopoly?","Where one firm serves cheapest — water, power grids — best regulated."],["Do patents create monopolies?","Temporary ones, deliberately — the price of incentivizing invention."]]},{"title":"Game Theory","brief":"Game theory models strategic interaction — where your best move depends on others' moves.","points":["Nash equilibrium: no player can gain by deviating alone.","Prisoner's dilemma: individual rationality yields collective ruin.","Repeated games enable cooperation through retaliation strategies.","Mechanism design: engineering games to get good outcomes."],"examples":["OPEC members tempted to cheat on quotas.","Auction design for spectrum sales raising billions."],"history":["Von Neumann and Morgenstern (1944); Nash (1950).","Nobel prizes multiplied as applications spread."],"uses":["Oligopoly pricing and antitrust.","Auction and market design.","Negotiations and contracts."],"qa":[["What is the prisoner's dilemma?","Both defect though both would do better cooperating — the core of collective-action problems."],["Does game theory assume selfishness?","It assumes preferences; behavioral game theory studies real ones."],["Where is it actually used?","Spectrum auctions, matching markets (kidneys, schools), and pricing."]]},{"title":"Behavioral Economics","brief":"Behavioral economics studies how people actually decide — biased, emotional, and predictably irrational.","points":["Loss aversion: losses hurt ~2x more than gains please.","Framing, anchoring, and defaults shape choices powerfully.","Present bias: we overvalue now versus later.","Nudges redesign choice architecture for better outcomes."],"examples":["401(k) auto-enrollment massively raising savings via defaults.","Organ-donor rates differing by opt-in vs opt-out framing."],"history":["Kahneman and Tversky's prospect theory (1979).","Thaler's nudge agenda; Nobel 2017."],"uses":["Policy design: saving, health, tax compliance.","Marketing and product design.","Improving the rationality assumption."],"qa":[["Are people irrational?","Boundedly rational — using heuristics that work mostly, fail systematically."],["What is a nudge?","A choice-preserving intervention steering toward better decisions."],["Does behavioral econ reject markets?","No — it refines the model of agents within them."]]},{"title":"Externalities","brief":"Externalities are costs or benefits falling on third parties — the classic reason markets fail and policy intervenes.","points":["Negative: pollution, congestion, secondhand smoke.","Positive: vaccinations, education, beautiful gardens.","Pigouvian taxes price negative externalities; subsidies boost positive ones.","Coase: with clear property rights and low transaction costs, parties can bargain to efficiency."],"examples":["Carbon taxes pricing climate damage.","Vaccination subsidies for herd-immunity spillovers."],"history":["Pigou (1920) proposed corrective taxes.","Coase (1960) showed bargaining can substitute."],"uses":["Environmental policy design.","Public health.","Intellectual property debates."],"qa":[["What is the Coase theorem?","With zero transaction costs, private bargaining fixes externalities regardless of rights assignment."],["Tax or cap-and-trade for pollution?","Tax fixes price; cap fixes quantity — each suits different uncertainties."],["Are externalities everywhere?","Nearly — which is why the concept is so powerful and so contested."]]},{"title":"Public Goods","brief":"Public goods — non-excludable and non-rival — are underprovided by markets, inviting free-riding and government provision.","points":["Non-excludable: can't keep non-payers out; non-rival: one person's use doesn't reduce others'.","Classic examples: national defense, lighthouses, basic research.","Free-rider problem: everyone waits for someone else to pay.","Club goods and common resources are the near-neighbors with different problems."],"examples":["GPS: a US-funded public good used worldwide free.","Open-source software as a privately provided public good."],"history":["Samuelson (1954) formalized public goods theory.","Ostrom (1990) showed communities can govern commons."],"uses":["Government budgeting for defense, research, infrastructure.","Philanthropy filling provision gaps.","Digital public goods policy."],"qa":[["Is healthcare a public good?","Mostly not technically (it's excludable and rival) — the case for public provision rests elsewhere."],["Can markets provide public goods?","Sometimes via bundling, philanthropy, or technology — but underprovision is typical."],["What is the tragedy of the commons?","Overuse of shared rival resources — distinct from public goods, solved differently."]]},{"title":"Labor Economics","brief":"Labor economics studies work: wages, employment, and how people and firms match in labor markets.","points":["Wages reflect productivity, bargaining power, and compensating differentials.","Minimum wages: small disemployment effects at moderate levels, per modern evidence.","Human capital (education, skills) drives lifetime earnings differences.","Discrimination and monopsony distort otherwise competitive outcomes."],"examples":["Card and Krueger's minimum-wage study reshaping the debate.","The college wage premium rewarding education."],"history":["Smith on compensating differentials (1776); modern empirical revolution (1990s+).","Nobel prizes for labor empiricists (Card, Angrist, Imbens 2021)."],"uses":["Minimum wage and labor regulation.","Education and training policy.","Immigration economics."],"qa":[["Do minimum wages kill jobs?","Modest hikes show small effects; large hikes risk more — context matters."],["Why do wages differ so much?","Skills, bargaining power, discrimination, luck, and compensating differentials."],["Will AI take all jobs?","History says tasks change more than work disappears — transitions are the pain."]]},{"title":"Economic Growth","brief":"Economic growth — rising output per person over time — is the main source of improved living standards.","points":["Solow model: capital, labor, and technology drive growth; diminishing returns limit capital alone.","Sustained growth comes from technological progress and ideas.","Institutions (property rights, rule of law) explain much cross-country difference.","Growth accounting decomposes observed growth into its sources."],"examples":["South Korea's transformation from poverty to riches in a generation.","The Industrial Revolution: sustained growth's historic takeoff."],"history":["Solow (1956); endogenous growth theory (Romer, 1990).","Institutions literature (Acemoglu et al.) explaining divergence."],"uses":["Development policy.","Long-run investing and forecasting.","Debating growth vs sustainability."],"qa":[["What causes growth?","Ideas, institutions, investment, and openness — technology is the engine."],["Can growth continue forever?","Decoupling growth from resources is the open question."],["Does growth help the poor?","Growth is the strongest correlate of poverty reduction historically."]]},{"title":"Business Cycles","brief":"Business cycles are the economy's rhythmic expansions and contractions — recessions interrupting growth.","points":["Phases: expansion, peak, contraction, trough.","Causes debated: demand shocks, supply shocks, financial frictions, expectations.","NBER dates US cycles; two GDP quarters is the folk rule, not the official one.","Stabilization policy aims to dampen cycles, not eliminate them."],"examples":["The Great Moderation (1985-2007) lulled policymakers.","COVID's cycle: the sharpest crash and fastest rebound on record."],"history":["Burns and Mitchell (1946) measured cycles; theories multiplied.","Real business cycle vs New Keynesian debate continues."],"uses":["Recession forecasting and preparation.","Countercyclical policy.","Business planning across the cycle."],"qa":[["What causes recessions?","Shocks plus propagation — financial, supply, demand, or policy mistakes."],["Can we prevent recessions?","Dampen, not prevent — and prevention attempts can backfire."],["How long do cycles last?","US expansions averaged ~5 years post-WWII; contractions under a year."]]},{"title":"Financial Markets","brief":"Financial markets move capital from savers to borrowers — pricing risk and funding enterprise.","points":["Functions: capital allocation, risk sharing, price discovery, liquidity.","Efficient markets hypothesis: prices reflect available information.","Behavioral finance documents systematic mispricing.","Regulation guards against fraud, manipulation, and systemic risk."],"examples":["IPOs funding startups; bonds funding infrastructure.","The 2010 flash crash showing market fragility."],"history":["Fama's efficient markets (1970); Shiller's behavioral critique.","Regulation evolving since 1929."],"uses":["Investing and retirement saving.","Corporate finance: raising capital.","Policymaking: market signals and stability."],"qa":[["Are markets efficient?","Mostly, in liquid markets — anomalies exist but are hard to exploit."],["Should I try to beat the market?","Index funds beat most active attempts after fees."],["What causes crashes?","Leverage, herding, and liquidity vanishing together."]]},{"title":"Banking","brief":"Banks take deposits, make loans, and operate the payment system — maturity-transforming the economy.","points":["Fractional reserves: banks lend most deposits, keeping a fraction.","Maturity transformation: short deposits fund long loans — profitable but run-prone.","Deposit insurance and lender-of-last-resort stop panics.","Capital regulation (Basel) limits leverage."],"examples":["Silicon Valley Bank's 2023 run: uninsured deposits fleeing.","The 2008 crisis: maturity transformation meeting bad mortgages."],"history":["Banking is centuries old; central banking stabilized it.","Basel Accords (1988+) set global capital rules."],"uses":["Credit for the economy.","Payment systems.","Financial stability policy."],"qa":[["Are banks safe?","Insured deposits are; uninsured large deposits carry run risk."],["What caused 2008?","Bad mortgage assets plus extreme leverage plus panic."],["Do we still need banks with fintech?","The functions persist; the institutions are evolving."]]},{"title":"Financial Crises","brief":"Financial crises — banking panics, crashes, sovereign defaults — follow patterns: leverage, euphoria, then panic.","points":["Minsky's cycle: stability breeds leverage breeds instability.","Contagion spreads through balance sheets and confidence.","Policy response: liquidity, recapitalization, stimulus.","Prevention: macroprudential regulation, sane leverage."],"examples":["1929 and the Great Depression.","2008: subprime to global meltdown.","1997 Asian crisis; 2010 euro crisis."],"history":["Kindleberger chronicled manias (1978); Reinhart-Rogoff data (2009).","Each crisis teaches; each generation forgets."],"uses":["Regulatory design.","Investor risk management.","Crisis preparedness."],"qa":[["Can crises be predicted?","Vulnerabilities can; timing barely — that's the trap."],["What ends a crisis?","Decisive liquidity, recapitalization, and demand support."],["Are we safer now?","Banks are; risks migrate to shadow banking."]]},{"title":"Income Inequality","brief":"Income inequality measures how unequally economic gains are shared — rising in many countries for decades.","points":["Measured by Gini coefficients, top shares, percentile ratios.","Drivers: skill premiums, globalization, declining unions, tax policy, technology.","Effects debated: incentives vs instability, health, and mobility.","Wealth inequality exceeds income inequality everywhere."],"examples":["US top-1% income share doubling since 1980.","Scandinavia combining growth with low inequality."],"history":["Kuznets curve (1955); Piketty's Capital (2014) revived the debate.","Empirical inequality research exploded."],"uses":["Tax and transfer design.","Education and labor policy.","Political economy."],"qa":[["Is inequality bad?","Extreme inequality correlates with instability; some inequality rewards effort."],["What reduces inequality?","Education, strong labor institutions, progressive taxes, transfers."],["Income or wealth inequality?","Both matter; wealth compounds across generations."]]},{"title":"Development Economics","brief":"Development economics studies how poor countries get rich — growth, poverty, and institutions.","points":["Poverty traps: low income to low investment to low income.","Institutions rule: property rights and governance explain divergence.","Randomized trials (Banerjee, Duflo, Kremer) revolutionized anti-poverty policy.","Aid debates: help vs harm vs irrelevance."],"examples":["East Asia's export-led miracles.","Microfinance's mixed report card.","Deworming's outsized schooling effects."],"history":["Development as a field from the 1940s-50s.","RCT revolution (2000s); Nobel 2019."],"uses":["Foreign aid design.","Poverty reduction strategy.","Understanding the wealth of nations."],"qa":[["Does foreign aid work?","Some does (health, specific programs); growth effects are debated."],["What ended extreme poverty fastest?","Broad-based economic growth, especially in China and India."],["Why are some countries still poor?","Institutions, geography, conflict, and history — no single cause."]]},{"title":"Environmental Economics","brief":"Environmental economics prices nature into decisions — correcting the externalities markets ignore.","points":["Pigouvian taxes and cap-and-trade internalize pollution costs.","Valuation methods price ecosystem services.","Discounting shapes climate policy: how much is the future worth?","Green growth debates: decoupling vs degrowth."],"examples":["The US SO2 trading program cutting acid rain cheaply.","Carbon pricing spreading across 40+ jurisdictions."],"history":["Pigou (1920); environmental econ grew with 1970s regulation.","Climate economics (Stern, Nordhaus) now central."],"uses":["Climate policy design.","Conservation finance.","Corporate sustainability."],"qa":[["Tax or cap for carbon?","Both work; tax gives price certainty, cap gives quantity certainty."],["What is the social cost of carbon?","Estimated damages per ton — central to policy, deeply uncertain."],["Can growth be green?","Decoupling is happening for some pollutants; carbon decoupling is the test."]]},{"title":"Health Economics","brief":"Health economics studies the peculiar market for health — asymmetric information, insurance, and life-and-death stakes.","points":["Arrow (1963): uncertainty and information gaps make health markets special.","Insurance creates moral hazard; mandates and risk adjustment manage it.","Cost-effectiveness (QALYs) guides spending decisions.","Systems vary: single-payer, multi-payer, market-based — all with trade-offs."],"examples":["The RAND experiment measuring how cost-sharing changes care use.","QALY thresholds guiding drug coverage decisions."],"history":["Field founded mid-1900s; grew with healthcare spending.","ACA (2010) was applied health economics at scale."],"uses":["Health policy design.","Hospital and insurer strategy.","Personal insurance choices."],"qa":[["Why is healthcare so expensive in the US?","Prices, administrative costs, and fee-for-service incentives — not more care."],["What is a QALY?","Quality-adjusted life year — the common yardstick for health value."],["Does universal healthcare work?","Every rich country has it in some form; designs and results vary."]]},{"title":"Education Economics","brief":"Education economics treats schooling as investment — in human capital with big private and social returns.","points":["Returns to education are high on average but vary by field and quality.","Signaling vs human capital: does school build skills or just certify them?","Early childhood investment has the highest returns.","Peer effects, teachers, and resources all matter — teachers most."],"examples":["The Perry Preschool study's lifelong returns.","College wage premiums varying hugely by major."],"history":["Schultz and Becker (1960s) founded human capital theory.","Education RCTs now guide policy."],"uses":["School funding and reform.","College and career decisions.","Workforce development."],"qa":[["Is college worth it?","On average yes, but it depends on cost, major, and completion."],["What matters most in schools?","Teacher quality, consistently."],["Does money matter for schools?","Yes — especially for disadvantaged students."]]},{"title":"Urban Economics","brief":"Urban economics explains cities — why they form, how land is used, and the costs of agglomeration.","points":["Agglomeration economies: firms and workers are more productive together.","Bid-rent: land goes to the highest-value use, shaping city structure.","Housing supply restrictions drive affordability crises.","Congestion, pollution, and crime are urban externalities to manage."],"examples":["Silicon Valley's agglomeration in tech.","Housing shortages where zoning blocks building."],"history":["Von Thünen (1826) to Alonso (1964) modeled land use.","Glaeser's Triumph of the City (2011) popularized the field."],"uses":["Housing and zoning policy.","Transportation planning.","Regional development."],"qa":[["Why are cities so productive?","Matching, sharing, and learning — density's triple dividend."],["What causes housing crises?","Mostly supply restrictions meeting strong demand."],["Will remote work kill cities?","It reshapes them; agglomeration forces persist."]]},{"title":"Industrial Organization","brief":"Industrial organization studies how firms compete — pricing, strategy, and market structure.","points":["Structure-conduct-performance: market structure shapes firm behavior shapes outcomes.","Pricing strategies: discrimination, bundling, predation.","Entry deterrence and strategic behavior.","Empirical IO estimates demand and market power from data."],"examples":["Airline price discrimination by booking time.","Microsoft's bundling antitrust battles."],"history":["Bain (1950s); game-theoretic revolution (1980s); empirical turn (2000s).","Guides modern antitrust."],"uses":["Antitrust and merger review.","Regulatory design.","Business strategy."],"qa":[["What is price discrimination?","Charging different prices by willingness to pay — often efficient."],["When should mergers be blocked?","When they substantially lessen competition — the agencies' test."],["Is big tech a monopoly problem?","Actively litigated; economics informs both sides."]]},{"title":"Econometrics","brief":"Econometrics is economics' measurement toolkit — statistics for testing theories and guiding policy.","points":["Regression estimates relationships; identification separates causation from correlation.","RCTs are the gold standard; natural experiments and IVs approximate it.","The credibility revolution demanded transparent research designs.","Big data and machine learning are reshaping empirical work."],"examples":["Minimum-wage studies using state policy differences.","Regression discontinuity at test-score cutoffs."],"history":["Tinbergen and Frisch founded it (1930s); Haavelmo formalized probability.","Angrist, Card, Imbens: the design-based revolution."],"uses":["Policy evaluation.","Forecasting.","Business analytics."],"qa":[["Correlation or causation?","Econometrics' central question — design is everything."],["What is an instrument?","A variable affecting treatment but not outcomes directly — isolating causation."],["Can ML replace econometrics?","It complements prediction; causal questions still need design."]]},{"title":"Keynesian Economics","brief":"Keynesian economics holds that demand drives output — and that governments can stabilize economies stuck below potential.","points":["Sticky prices and wages let demand shortfalls cause unemployment.","The multiplier: spending ripples through the economy.","Liquidity traps: when rates hit zero, fiscal policy must lead.","New Keynesians rebuilt the theory on microfoundations."],"examples":["The General Theory (1936) answering the Depression.","2008-09 stimulus debates replaying Keynes vs skeptics."],"history":["Keynes (1936); Hicks-Hansen IS-LM; New Keynesian DSGE models.","Dominant in central banks and treasuries."],"uses":["Recession-fighting policy.","Central bank frameworks.","Understanding demand-driven slumps."],"qa":[["Is Keynesianism just 'spend more'?","No — it's countercyclical: save in booms, spend in busts."],["What is the liquidity trap?","When rates can't fall further and money hoarding defeats monetary policy."],["Do Keynesians ignore supply?","Short-run focus, yes — long-run growth is supply-side."]]},{"title":"Classical and Neoclassical Economics","brief":"Classical and neoclassical economics built the framework of optimizing agents and equilibrating markets.","points":["Smith, Ricardo, Mill: value, trade, and growth classics.","Marginal revolution (1870s): Jevons, Menger, Walras founded modern price theory.","General equilibrium: all markets clearing simultaneously.","Welfare theorems: competitive equilibria are efficient (under conditions)."],"examples":["Walrasian auctioneer as metaphor for market clearing.","Marginal utility explaining the diamond-water paradox."],"history":["1776-1870s classical; 1870s+ neoclassical synthesis.","Samuelson mathematized it (1947)."],"uses":["The benchmark model of economics.","Policy: the efficiency case for markets.","Teaching foundations."],"qa":[["What did the marginal revolution change?","Value from marginal utility, not labor — enabling modern price theory."],["Are the welfare theorems realistic?","They need perfect competition, no externalities — a benchmark, not reality."],["Is neoclassical economics dead?","No — extended by behavioral, information, and institutional economics."]]},{"title":"Austrian Economics","brief":"Austrian economics emphasizes individual action, subjective value, and spontaneous order — skeptical of aggregates and intervention.","points":["Methodological individualism: only individuals act.","Subjective value: worth is in the eye of the valuer.","Business cycle theory: credit expansion causes malinvestment.","Spontaneous order: markets as undesigned coordination."],"examples":["Menger's Principles (1871) founding the school.","Hayek's Road to Serfdom (1944) and Nobel (1974)."],"history":["Vienna 1870s+; Mises, Hayek, Rothbard.","Influential in libertarian thought and central-bank criticism."],"uses":["Critiques of central banking and stimulus.","Entrepreneurship theory.","Debates on planning vs markets."],"qa":[["Do Austrians reject math?","They're skeptical of aggregates and prediction, not all formalism."],["What is malinvestment?","Credit-fueled projects viable only at distorted rates — the bust corrects them."],["Is Austrian economics mainstream?","Its insights (subjectivism, knowledge problems) influenced the mainstream; the school stays heterodox."]]},{"title":"Cryptocurrency and Digital Money","brief":"Digital currencies — Bitcoin to CBDCs — challenge what money is and who issues it.","points":["Bitcoin: decentralized scarcity via proof-of-work.","Stablecoins: crypto dollars for payments and DeFi.","CBDCs: central banks' digital answer.","Monetary economics questions: volatility, runs, and sovereignty."],"examples":["El Salvador's Bitcoin experiment.","Stablecoin volumes rivaling payment networks."],"history":["Bitcoin whitepaper (2008); boom-bust cycles since.","Regulation racing to catch up."],"uses":["Payments innovation.","Financial inclusion debates.","Monetary sovereignty concerns."],"qa":[["Is Bitcoin money?","It's a speculative asset with money-like uses — the debate continues."],["What are CBDCs?","Central-bank digital currencies — digital cash, with design trade-offs."],["Will crypto replace banks?","It competes at the edges; the core financial system adapts."]]},{"title":"The Economics of Happiness","brief":"Happiness economics measures well-being directly — asking what actually makes lives go well.","points":["Easterlin paradox: richer countries aren't much happier past a point.","Relative income matters: comparison is the thief of joy.","Unemployment devastates well-being beyond income loss.","Policy experiments: well-being budgets (New Zealand)."],"examples":["Bhutan's Gross National Happiness.","World Happiness Report rankings."],"history":["Easterlin (1974); Layard, Kahneman advancing measurement.","Growing policy influence."],"uses":["Beyond-GDP policymaking.","Work and workplace design.","Personal life decisions."],"qa":[["Does money buy happiness?","Up to comfort, yes; beyond, relationships and purpose dominate."],["Should policy maximize happiness?","Proponents say yes; critics cite measurement and manipulation worries."],["What makes countries happy?","Trust, health, freedom, generosity — and decent incomes."]]},{"title":"Stock Markets","brief":"Stock markets let investors own pieces of companies — pricing ownership claims through continuous trading.","points":["Shares represent residual claims on profits and assets.","Primary markets (IPOs) raise capital; secondary markets provide liquidity.","Indices (S&P 500) track baskets as market benchmarks.","Volatility reflects uncertainty; diversification tames it."],"examples":["An IPO pricing shares for public trading.","Index funds tracking the S&P 500 for millions of savers."],"history":["Amsterdam (1602) hosted the first stock market.","Regulation after 1929; electronic trading from the 1970s."],"uses":["Retirement saving and wealth building.","Corporate capital raising.","Economic sentiment gauging."],"qa":[["Should I pick stocks?","Index funds beat most stock-picking after fees and taxes."],["What moves stock prices?","Earnings expectations, rates, and sentiment — in that rough order."],["Are stocks risky?","Short-term yes; long-term diversified holdings have rewarded patience."]]},{"title":"Bonds and Fixed Income","brief":"Bonds are loans to governments and corporations — promising fixed payments, sensitive to interest rates.","points":["Price moves inversely to yield: rates up, prices down.","Credit risk: the chance the issuer defaults.","Duration measures interest-rate sensitivity.","The yield curve reflects growth and policy expectations."],"examples":["Treasury bonds funding government deficits.","Corporate bonds financing expansion."],"history":["Centuries old; modern bond markets from the 1900s.","Central to pension and insurance investing."],"uses":["Conservative investing and income.","Government and corporate finance.","Recession forecasting via the curve."],"qa":[["Are bonds safe?","Safer than stocks, but rate and credit risk remain."],["Why do bond prices fall when rates rise?","Fixed payments are worth less discounted at higher rates."],["What is duration?","The weighted-average time to cash flows — and the price sensitivity gauge."]]},{"title":"Entrepreneurship","brief":"Entrepreneurship turns ideas into firms — the micro-engine of innovation and job creation.","points":["Founders bear risk for residual returns.","Venture capital funds high-risk, high-reward startups.","Most startups fail; the few winners pay for the rest.","Ecosystems (talent, capital, culture) determine startup rates."],"examples":["A garage startup becoming a global platform.","Small businesses creating most net new jobs."],"history":["Schumpeter (1911) made the entrepreneur central.","Silicon Valley model spreading globally."],"uses":["Innovation and economic dynamism.","Career path for the ambitious.","Policy: fostering startup ecosystems."],"qa":[["What makes startups succeed?","Team, timing, and market — ideas are the easy part."],["Should I raise venture capital?","Only if the business can scale fast enough to justify it."],["Do entrepreneurs need luck?","Enormous amounts — skill buys more lottery tickets."]]},{"title":"Mergers and Acquisitions","brief":"M&A recombines companies — for synergies, market power, or talent — with a mixed record of success.","points":["Motives: synergies, scale, market power, acqui-hires.","Most acquirers overpay; targets' shareholders gain most.","Antitrust reviews block anti-competitive deals.","Integration — culture and systems — decides outcomes."],"examples":["Disney acquiring Pixar: a creative synergy success.","Failed mergers destroyed by culture clashes."],"history":["Merger waves since the 1890s.","Modern antitrust scrutiny intensifying."],"uses":["Corporate strategy.","Investment banking.","Competition policy."],"qa":[["Do mergers work?","Targets win; acquirers often don't — discipline matters."],["Why do CEOs love deals?","Growth, empire, and sometimes genuine synergy — incentives skew toward doing them."],["When should regulators block?","When competition would substantially lessen."]]},{"title":"Economic Indicators","brief":"Economic indicators — GDP, jobs, inflation, sentiment — are the dashboard dials of the economy.","points":["Leading (yield curve, orders), coincident (jobs, output), lagging (unemployment duration).","Releases move markets; revisions remind us data is fuzzy.","Soft data (surveys) vs hard data (spending).","No single indicator tells the story — triangulation does."],"examples":["Payrolls Friday moving markets monthly.","PMI surveys signaling manufacturing turns."],"history":["National accounts (1940s); indicators proliferating since.","Nowcasting (2010s) estimates GDP in real time."],"uses":["Investing and business planning.","Policy decisions.","Journalism and public understanding."],"qa":[["Which indicator matters most?","Jobs and inflation for policy; depends on your question."],["Why do markets react to data?","Surprises change rate and earnings expectations."],["Can indicators predict recessions?","The yield curve and leading index have the best records — imperfectly."]]},{"title":"Consumer Behavior","brief":"Consumer spending is ~70% of the US economy — understanding it is macroeconomics' front line.","points":["Consumption follows income but smooths via saving and borrowing.","Confidence surveys predict spending turns.","Wealth effects: rising assets boost spending.","Debt levels constrain future consumption."],"examples":["Stimulus checks boosting spending within weeks.","Housing wealth driving consumption booms and busts."],"history":["Keynes' consumption function (1936); Friedman PIH; Modigliani life-cycle.","Behavioral insights refining the models."],"uses":["Retail strategy.","Recession forecasting.","Stimulus design."],"qa":[["What drives spending?","Income, wealth, confidence, credit access — in that rough order."],["Do stimulus checks work?","Yes for constrained households — high MPC, fast spending."],["Why do consumers matter so much?","One person's spending is another's income — the circular flow."]]},{"title":"The Great Depression","brief":"The Great Depression (1929-39) was the defining economic catastrophe — reshaping theory and policy forever.","points":["Causes: stock crash, bank failures, gold-standard rigidity, policy errors.","Friedman and Schwartz blamed monetary collapse; others stress demand and debt.","Unemployment hit 25%; output fell by a third.","Legacy: deposit insurance, central-bank activism, Keynesian economics."],"examples":["Bank runs wiping out savings before deposit insurance.","The New Deal's experiments in recovery."],"history":["1929 crash; 1930-33 banking collapse; slow recovery.","Studied ever since as the policy-failure archetype."],"uses":["Central banking doctrine.","Financial regulation.","The benchmark for every crisis since."],"qa":[["What caused the Depression?","A cascade: crash, bank failures, monetary tightening, global gold-standard trap."],["Could it happen again?","Safeguards (deposit insurance, active central banks) make a repeat unlikely — vigilance required."],["Did the New Deal end it?","It helped; WWII spending finished the job — debated ever after."]]},{"title":"Globalization","brief":"Globalization wove national economies into one — lifting billions from poverty while straining workers and politics.","points":["Trade, capital flows, and supply chains integrated markets.","China and India's rise cut global poverty dramatically.","Displaced workers in rich countries fueled backlash.","Partial deglobalization now: reshoring, friend-shoring."],"examples":["A smartphone's 40-country supply chain.","The China shock's US labor-market effects."],"history":["First wave (1870-1914); second (1945-2008); reassessment since.","WTO, containers, and the internet enabled it."],"uses":["Trade and industrial policy.","Development strategy.","Geopolitics."],"qa":[["Was globalization good?","Hugely for global poverty; painful for some workers — both true."],["Is globalization ending?","Slowing and reshaping, not ending — integration persists."],["What comes next?","Regional blocs, resilient supply chains, digital globalization."]]},{"title":"Poverty Economics","brief":"Poverty economics studies why people stay poor and what actually lifts them out.","points":["Poverty traps: low assets to low returns to low assets.","Ultra-poor graduation programs show big, lasting gains.","Cash transfers are among the most effective interventions.","Growth plus safety nets beats either alone."],"examples":["GiveDirectly's cash transfers transforming villages.","BRAC's graduation model replicated globally."],"history":["RCT revolution (2000s); Nobel 2019.","Extreme poverty falling for decades until COVID."],"uses":["Aid and philanthropy design.","Welfare policy.","Development strategy."],"qa":[["What works against poverty?","Cash, graduation programs, health, and education — evidence-backed."],["Does aid work?","Targeted programs do; the debate is about growth effects."],["Can poverty be ended?","Extreme poverty could be nearly ended this century — with sustained effort."]]},{"title":"The Future of Economics","brief":"Economics is being reshaped by AI, big data, and new questions — from automation to climate to well-being.","points":["AI transforms both the economy studied and the tools studying it.","Climate economics moves from niche to core.","Well-being metrics challenge GDP's monopoly.","New data (satellites, transactions) enables real-time economics."],"examples":["AI copilots for econometric research.","Satellite data measuring poverty and growth."],"history":["The field reinvents itself each generation.","Current frontier: causal ML, climate, inequality."],"uses":["Careers: the most versatile social science.","Policy: evidence-based design.","Understanding tomorrow's economy."],"qa":[["Will AI replace economists?","It augments analysis; judgment and theory remain human."],["What should students learn?","Core theory, causal inference, coding, and communication."],["Is economics too narrow?","It's expanding — behavior, institutions, nature all inside now."]]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var ti=(((s-1)/6)|0)%TOPICS.length, ai=(s-1)%6;
  var angle=ANGLES[ai];
  if(opts.genre&&ANGLES.indexOf(opts.genre)>=0)angle=opts.genre;
  var t=TOPICS[ti],title=t.title,brief=t.brief,topic=t;
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  if(ctopic){title=ctopic;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';
    topic={title:title,brief:brief,points:t.points,examples:t.examples,history:t.history,uses:t.uses,qa:t.qa,demo:t.demo};}
  var id=PREFIX+pad(s);
  var content=buildContent(topic,angle);
  var demo=topic.demo||defaultDemo();
  return{id:id,title:title+' ('+angle+')',description:brief,genre:angle,type:RECORD_KIND,content:content, content_completeness:'stub',
    stub_note:'Topic stub: the topic title and its one-line brief are real; the full guide article is not yet written. This record does not present shell text as a complete guide.',demo:demo,src:SRC,_seed:s};
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(ANGLES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.summary!=='string'||r.content.summary.length<40)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-economics-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:ANGLES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('economics',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();